 #[test]fn whole_warning_query_and_inline_rng_match2048_native_executions(){let mut hash=2166136261u32;for n in 0..2048usize{let mut actors=vec![Actor{slot:0,position:[1800,1800],family:4,class:0,phase:1,flags31:4,flags8a:0,aim:60,role:-1,group:0}];for i in 1..=21usize{actors.push(Actor{slot:i as u8,position:[900+i as i16*3,800+i as i16*5],family:4,class:0,phase:1,flags31:4|(n%4)as u8,flags8a:0,aim:(n*(i+1)+i*7)as i8,role:i as i8,group:1});}let t=&mut actors[1];let ds=[-32,-23,-22,-14,-2,0,7,8,16,31];t.position=[520+ds[n%10],520+ds[n/10%10]];t.family=[4,6,24,25,30,32,34,36,38,-1][n%10];t.class=[0,1,2,15][n/10%4];t.aim=if n%5==0{0}else{(n*17)as i8};t.role=[-1,0,1][n/40%3];t.group=if n/9%3==0{0}else{1};t.phase=[0,1,2,18][n/40%4];t.flags8a=if n/160%2==0{0}else{16};t.flags31=if n/80%2==0{4}else{0}|(n%4)as u8;if n>=1024{t.position=[520+((n%5)as i16-2)*5,520+((n/5%5)as i16-2)*5];t.family=4;t.class=0;t.aim=if n%5==0{0}else{[60,-128,127][n%3]};t.role=-1;t.group=1;t.phase=1;t.flags8a=0;t.flags31=5;}
 let(mut flags,mut wait)=((n*13)as u8,if n/11%2==0{0u8}else{7u8});let counter=if n/7%3==0{0}else{3};let mut rng=crate::original_combat::OriginalRng{words:std::array::from_fn(|i|(n*(i+1)+i+1)as u32),multiplayer:n%2!=0};let(mut calls,mut trace)=(0u32,2166136261u32);if let Some(target)=query(&actors,[520,520]).filter(|&t|admitted(0,t,counter)){assert_eq!(target.group,1);if wait==0{for i in 1..=21usize{if(n+i)%4==0{continue;}let a=actors[i];let first=rng.next_u32();let second=rng.next_u32();let p=scatter(a.position,a.aim,first,second);for v in[i as u32,p[0]as u32,p[1]as u32,2,1]{trace=(trace^v).wrapping_mul(16777619);}calls+=1;}}flags&=!1;wait=68;}
 let values=[n as u32,19,9,u32::from(flags),u32::from(wait),rng.words[0],rng.words[1],rng.words[2],rng.words[3],rng.words[4],2,calls,trace,SHAPE_POINTER];if let Ok(path)=std::env::var("NATIVE_WARNING_ORACLE"){let text=std::fs::read_to_string(path).unwrap();let v:serde_json::Value=serde_json::from_str(text.lines().nth(n).unwrap()).unwrap();let expected=["scenario","g0flags","g0wait","g1flags","g1wait","rng0","rng1","rng2","rng3","rng4","context","calls","trace","shape"].map(|k|v[k].as_u64().unwrap()as u32);assert_eq!(values,expected,"scenario{n}");}for v in values{hash=(hash^v).wrapping_mul(16777619);}}assert_eq!(hash,527670769,"real646b0/44f730/644d0;525a0 endpoint leaf explicit");}
